def tensor_fp8_linear(
    source: torch.Tensor,
    packed_weight: TensorFP8LinearWeight,
    *,
    plan: Plan | None = None,
    expected_m: int | None = None,
    bias: torch.Tensor | None = None,
    out_dtype: torch.dtype = torch.bfloat16,
    stream: object = None,
) -> torch.Tensor:
